{"operation":"run_python","code":"
import itertools, numpy as np

# A valid die labeling: opposite pairs sum to 7
# face number -> outward normal
lab = {1:(0,0,1), 6:(0,0,-1), 2:(1,0,0), 5:(-1,0,0), 3:(0,1,0), 4:(0,-1,0)}

# generate all 24 proper rotation matrices (det=+1, orthogonal, integer)
def rots():
    R=[]
    for perm in itertools.permutations(range(3)):
        for signs in itertools.product([1,-1],repeat=3):
            M=np.zeros((3,3),dtype=int)
            for i,(p,s) in enumerate(zip(perm,signs)):
                M[i,p]=s
            if round(np.linalg.det(M))==1:
                R.append(M)
    return R
RS=rots()
print("number of rotations:", len(RS))

hole_dir=np.array([1,0,0])   # the side of the box with the hole (a vertical side)
top_dir =np.array([0,0,1])   # up

tops=set()
count=0
for M in RS:
    # after rotation M, face with normal n has normal M@n
    num_at_hole=None; num_at_top=None
    for num,n in lab.items():
        v=M@np.array(n)
        if tuple(v)==tuple(hole_dir): num_at_hole=num
        if tuple(v)==tuple(top_dir):  num_at_top=num
    if num_at_hole==4:
        count+=1
        tops.add(num_at_top)
print("orientations with 4 at the hole:", count)
print("possible top faces:", sorted(tops))

# sanity: what if the hole were in the TOP of the box?
tops_top=set()
for M in RS:
    for num,n in lab.items():
        if tuple(M@np.array(n))==(0,0,1) and num==4:
            tops_top.add(num)
print("if hole were on top, top face would be:", sorted(tops_top))
